Here are turn-by-turn walking directions, placed right below the café.

```svelte file=lib/Directions.svelte
<script>
  import { Section, Action, List, ListRow } from 'design';
  import NavigationArrow from 'phosphor-svelte/lib/NavigationArrow';
  import PaperPlaneTilt from 'phosphor-svelte/lib/PaperPlaneTilt';

  let started = $state(false);
  let sent = $state(false);
  let step = $state(0);

  const steps = [
    { label: 'Head north on Pellory Street', sub: '0.2 mi · past the corner bakery', time: '2:38 PM' },
    { label: 'Turn right onto Thistlewick Road', sub: '0.25 mi · cross at the lights', time: '2:42 PM' },
    { label: 'Enter Calloway Gardens by the east gate', sub: '0.3 mi · shaded path, keep left at the fountain', time: '2:47 PM' },
    { label: 'Exit onto Quillfeather Lane', sub: '0.15 mi · café is on your left', time: '2:53 PM' },
    { label: 'Arrive at Wrenhollow Coffee', sub: '14 Quillfeather Lane', time: '2:56 PM' }
  ];
</script>

<Section title="Walking directions" kicker="On foot · 0.9 mi · 18 min">
  <List>
    {#each steps as s, i}
      <ListRow
        index={i + 1}
        label={s.label}
        sub={s.sub}
        trailing={s.time}
        current={started && step === i}
        onclick={() => (step = i)}
      />
    {/each}
  </List>
  <p class="m-meta">Mostly flat, step-free all the way.
Leave 27 Pellory Street at 2:38 PM to arrive by 2:56 PM.</p>
  {#snippet actions()}
    <Action
      label={started ? 'Route started' : 'Start walking route'}
      sublabel={started ? `Step ${step + 1} of ${steps.length}` : '18 min to Wrenhollow'}
      icon={NavigationArrow}
      primary
      disabled={started}
      onclick={() => {
        started = true;
        step = 0;
      }}
    />
    <Action
      label={sent ? 'Sent to phone' : 'Send to phone'}
      icon={PaperPlaneTilt}
      disabled={sent}
      onclick={() => (sent = true)}
    />
  {/snippet}
</Section>
```

